 // Verification-target methods. They live in a dedicated `#[verus_verify]` impl
 // block so that only the in-scope functions are checked (the self-less
 // associated functions `from_mmio_address` / `from_number` require an enclosing
 // `#[verus_verify]` impl to resolve), while the untouched constructors above are
 // left out of verification scope.
 #[verus_verify]
 impl PhysicalAddress {
     ///
     /// # Description
     ///
     /// Constructs a physical address from a memory-mapped I/O address.
     ///
     /// # Parameters
     ///
     /// - `addr`: The memory-mapped I/O address.
     ///
     /// # Return Values
     ///
     /// Upon success, a physical address associated with the given memory-mapped I/O address is
     /// returned. Upon failure, an error is returned instead.
     ///
     /// # Safety
     ///
     /// Behavior is undefined if the provided memory-mapped I/O address is invalid.
     ///
     // Deliberately bypasses the RAM-range validity check (MMIO GPAs may lie
     // outside tracked RAM). On success it is pure identity wrapping
     // (`r@ == addr@`); the `unsafe` contract — that `addr` denotes a valid MMIO
     // frame — is encoded as `requires` (frame-representability) so the result
     // satisfies the type invariant and may later flow into `into_frame_number`.
     #[verus_spec(result =>
         requires
             spec_frame_number(addr@) <= spec_max_frame_number(),
         ensures
             result is Ok,
             result matches Ok(r) ==> r@ == addr@ && r.inv(),
     )]
     pub unsafe fn from_mmio_address(addr: VirtualAddress) -> Result<Self, Error> {
         Ok(Self(addr))
     }

     ///
     /// # Description
     ///
     /// Constructs a [`PhysicalAddress`] from a [`FrameNumber`].
     ///
     /// # Parameters
     ///
     /// - `frame`: The frame number.
     ///
     /// # Returns
     ///
     /// A [`PhysicalAddress`] associated with the given `frame_number`.
     ///
     // The produced address is the frame's base address (`frame * FRAME_SIZE`).
     // The result is page-aligned (`result@ % FRAME_SIZE == 0`) and carries the
     // type invariant (`result.inv()`), so its sole caller can build a `FrameAddress`
     // (alignment) and later project it back with `into_frame_number` (`inv()`).
     #[verus_spec(result =>
         ensures
             result@ == spec_from_number(spec_frame_raw_value(frame)),
             result@ % spec_page_size() == 0,
             result.inv(),
     )]
     pub fn from_number(frame: FrameNumber) -> Self {
         let frame_raw: usize = frame.into_raw_value();
         let page_size: usize = mem::FRAME_SIZE;
         proof! {
             // No-overflow: `frame_raw * page_size <= usize::MAX`. With
             // `frame_raw <= usize::MAX / page_size - 1` and `page_size > 0`, the
             // product stays within `usize`.
             let p: int = spec_page_size();
             let fr: int = spec_frame_raw_value(frame);
             let m: int = usize::MAX as int;
             lemma_fundamental_div_mod(m, p);
             lemma_mod_division_less_than_divisor(m, p);
             assert(p * (m / p) <= m);
             assert(fr * p <= m) by (nonlinear_arith)
                 requires
                     p > 0,
                     fr >= 0,
                     fr <= m / p - 1,
                     p * (m / p) <= m,
             ;
         }
         let addr: usize = frame_raw * page_size;

